export const FIXED_DT=1/120;
export const wrapAngle=a=>Math.atan2(Math.sin(a),Math.cos(a));
export const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
// Limit full-lock steering by lateral acceleration, so steering gets gentler at speed.
// state.steer remains the actual wheel angle normalized by the low-speed maximum (.52 rad).
export const steeringLimit=speed=>Math.min(.52,Math.atan(7.5*2.7/Math.max(speed*speed,1)));
export function manualSteering(previous,direction,dt=FIXED_DT){
 const target=clamp(direction,-1,1);
 const rate=target===0?3.2:Math.sign(previous)!==Math.sign(target)&&Math.abs(previous)>.01?3.2:1.6;
 return previous+clamp(target-previous,-rate*dt,rate*dt);
}
export function nearest(road,x,z){let best=Infinity,result;for(let i=0;i<road.points.length-1;i++){const a=road.points[i],b=road.points[i+1],dx=b.x-a.x,dz=b.z-a.z,len2=dx*dx+dz*dz;const t=clamp(((x-a.x)*dx+(z-a.z)*dz)/len2,0,1),px=a.x+t*dx,pz=a.z+t*dz,d2=(x-px)**2+(z-pz)**2;if(d2<best){best=d2;const len=Math.sqrt(len2);result={index:i,t,x:px,z:pz,distance:Math.sqrt(d2),signed:((x-px)*dz-(z-pz)*dx)/len,heading:Math.atan2(dx,dz),s:road.distances[i]+t*len};}}return result;}
export function pointAt(road,s){s=((s%road.length)+road.length)%road.length;let lo=0,hi=road.distances.length-1;while(hi-lo>1){const mid=(lo+hi)>>1;if(road.distances[mid]>s)hi=mid;else lo=mid;}const a=road.points[lo],b=road.points[lo+1],t=(s-road.distances[lo])/(road.distances[lo+1]-road.distances[lo]);return{x:a.x+(b.x-a.x)*t,z:a.z+(b.z-a.z)*t,heading:Math.atan2(b.x-a.x,b.z-a.z)};}
export function initialState(road){const p=pointAt(road,0);return{x:p.x,z:p.z,yaw:p.heading,speed:0,steer:0,time:0,lap:1,lapTime:0,travel:0,previousS:0,deviation:0,offroadTime:0,collisions:0,errorSum:0,samples:0,finishedLaps:[],lastCollision:-10};}
export function referenceControl(state,road){const n=nearest(road,state.x,state.z),lookahead=5+Math.abs(state.speed)*.72,target=pointAt(road,n.s+lookahead);const alpha=wrapAngle(Math.atan2(target.x-state.x,target.z-state.z)-state.yaw);const steer=clamp(Math.atan2(2*2.7*Math.sin(alpha),lookahead)/steeringLimit(state.speed),-1,1);let curvature=0;for(let d=0;d<48;d+=6){const a=pointAt(road,n.s+d),b=pointAt(road,n.s+d+6);curvature=Math.max(curvature,Math.abs(wrapAngle(b.heading-a.heading))/6);}const targetSpeed=clamp(Math.sqrt(4.5/Math.max(curvature,.006)),6,27);return{steer,throttle:clamp((targetSpeed-state.speed)*.4,0,1),brake:clamp((state.speed-targetSpeed)*.45,0,1),handbrake:false};}
export function driveScore(s){return s.samples?Math.round(clamp(100-32*(s.errorSum/s.samples)-4*s.offroadTime-8*s.collisions,0,100)):null;}
export function step(state,input,road,dt=FIXED_DT){const n=nearest(road,state.x,state.z),offroad=n.distance>road.width/2;const targetSteer=clamp(input.steer,-1,1)*steeringLimit(state.speed)/.52;state.steer+=(targetSteer-state.steer)*Math.min(1,dt*6);const acceleration=input.throttle*8-input.brake*15-(input.handbrake?18:0)-.22*state.speed-.006*state.speed**2-(offroad?state.speed*1.8:0);state.speed=clamp(state.speed+acceleration*dt,0,38);const wheelLimit=steeringLimit(state.speed)/.52;state.steer=clamp(state.steer,-wheelLimit,wheelLimit);state.yaw=wrapAngle(state.yaw+state.speed/2.7*Math.tan(state.steer*.52)*dt*(input.handbrake?.8:1));state.x+=Math.sin(state.yaw)*state.speed*dt;state.z+=Math.cos(state.yaw)*state.speed*dt;const after=nearest(road,state.x,state.z);state.deviation=after.signed;state.time+=dt;state.lapTime+=dt;state.errorSum+=Math.abs(after.signed)*dt;state.samples+=dt;if(after.distance>road.width/2)state.offroadTime+=dt;
 const wall=road.width/2+2.6;if(after.distance>wall){const scale=wall/after.distance;state.x=after.x+(state.x-after.x)*scale;state.z=after.z+(state.z-after.z)*scale;state.speed*=.55;if(state.time-state.lastCollision>1){state.collisions++;state.lastCollision=state.time;}}
 let delta=after.s-state.previousS;if(delta>road.length/2)delta-=road.length;if(delta<-road.length/2)delta+=road.length;if(Math.abs(delta)<3)state.travel+=delta;
 let completed=null;if(state.previousS>road.length*.9&&after.s<road.length*.1&&state.travel>road.length*.92){completed={lap:state.lap,time:state.lapTime,score:driveScore(state),offroadTime:state.offroadTime,collisions:state.collisions};state.finishedLaps.push(completed);state.lap++;state.lapTime=0;state.travel=0;}
 state.previousS=after.s;return{nearest:after,offroad:after.distance>road.width/2,completed};}
